public class Main {
    public static void main(String[] args) {
        int n = 2;
        switch (n) {
            case 1:
                System.out.println("一条");
            case 2:
                System.out.println("两条");
            case 3:
                System.out.println("三条");
                break;
            default:
                System.out.println("数不清");
        }
    }
}

